const data = $node['Handle Failure'].json;
return [{
  json: {
    original_filename: data.originalFilename,
    renamed_filename: data.failedFilename,
    timestamp: data.timestamp,
    tags: '',
    summary_file: '',
    status: 'failed',
    error_message: data.errorMessage
  }
}];

const meta = $node['Prepare Input'].json;
const rawError = $json.error ?? $json;
let errorMessage = rawError?.message ?? rawError?.description ?? rawError;
if (typeof errorMessage !== 'string') {
  try { errorMessage = JSON.stringify(errorMessage); } catch (_) { errorMessage = 'Unknown processing error'; }
}
errorMessage = String(errorMessage || 'Unknown processing error').slice(0, 1000);

const failedFilename = Date.now() + '_' + meta.originalFilename;
const failedPath = meta.failedDir + '\\' + failedFilename;
const psLiteral = (value) => "'" + String(value).replace(/'/g, "''") + "'";
const moveScript = [
  "$ErrorActionPreference = 'Stop'",
  'New-Item -ItemType Directory -Path ' + psLiteral(meta.failedDir) + ' -Force | Out-Null',
  'if (Test-Path -LiteralPath ' + psLiteral(meta.sourcePath) + ') {',
  '  Move-Item -LiteralPath ' + psLiteral(meta.sourcePath) + ' -Destination ' + psLiteral(failedPath) + ' -Force',
  '}'
].join("\r\n");

return [{
  json: {
    ...meta,
    timestamp: new Date().toISOString(),
    status: 'failed',
    errorMessage,
    failedFilename,
    failedPath,
    moveToFailedCommand: 'powershell.exe -NoProfile -NonInteractive -ExecutionPolicy Bypass -EncodedCommand ' + Buffer.from(moveScript, 'utf16le').toString('base64')
  }
}];

const data = $node['Parse Ollama Response'].json;
return [{
  json: {
    original_filename: data.originalFilename,
    renamed_filename: data.renamedFilename,
    timestamp: data.timestamp,
    tags: data.tags.join(', '),
    summary_file: data.summaryFilePath,
    status: 'success',
    error_message: ''
  }
}];

const meta = $node['Normalize Extracted Text'].json;
let raw = $json.response ?? $json.data?.response ?? $json.body?.response ?? $json.data ?? $json.body ?? $json;

if (typeof raw === 'string') {
  raw = raw.trim().replace(/^\`\`\`(?:json)?\s*/i, '').replace(/\s*\`\`\`$/, '');
  try { raw = JSON.parse(raw); } catch (_) { raw = { summary: raw, tags: [] }; }
}

if (raw && typeof raw.response === 'string' && raw.summary === undefined) {
  const nested = raw.response.trim().replace(/^\`\`\`(?:json)?\s*/i, '').replace(/\s*\`\`\`$/, '');
  try { raw = JSON.parse(nested); } catch (_) { raw = { summary: nested, tags: [] }; }
}

const clean = (value) => String(value ?? '')
  .replace(/^\s*(?:[-*•]|\d+[.)])\s*/, '')
  .replace(/^#+\s*/, '')
  .trim();

let points = raw?.summary ?? raw?.bullet_points ?? raw?.bullets ?? [];
if (!Array.isArray(points)) {
  points = String(points)
    .split(/\n+/)
    .map(clean)
    .filter((line) => line && !/^tags?\s*:/i.test(line));
}
points = points.map(clean).filter(Boolean).slice(0, 3);

const sourceSentences = meta.text
  .replace(/\s+/g, ' ')
  .split(/(?<=[.!?])\s+/)
  .map(clean)
  .filter(Boolean);
while (points.length < 3) {
  points.push(sourceSentences[points.length] || sourceSentences[0] || 'No additional summary point was available.');
}

let tags = raw?.tags ?? raw?.keywords ?? [];
if (!Array.isArray(tags)) tags = String(tags).split(/[,\n|/]+/);
tags = tags.map(clean).map((tag) => tag.replace(/^#/, '')).filter(Boolean).slice(0, 3);

if (tags.length < 3) {
  const stop = new Set(['this','that','with','from','have','were','will','would','could','about','there','their','which','when','where','document','summary','text','into','also','than','then','they','them','these','those','your','been','being','does','each']);
  const counts = {};
  for (const word of meta.text.toLowerCase().match(/[a-z][a-z0-9-]{3,}/g) || []) {
    if (!stop.has(word)) counts[word] = (counts[word] || 0) + 1;
  }
  for (const [word] of Object.entries(counts).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))) {
    if (!tags.some((tag) => tag.toLowerCase() === word)) tags.push(word);
    if (tags.length === 3) break;
  }
}
while (tags.length < 3) tags.push(['document', 'summary', 'local-ai'][tags.length]);

const safeTags = tags.map((tag, index) => {
  const safe = tag.toLowerCase()
    .normalize('NFKD')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 24);
  return safe || ['document', 'summary', 'local-ai'][index];
});

const now = new Date();
const date = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Kolkata', year: 'numeric', month: '2-digit', day: '2-digit'
}).format(now);
const timestamp = now.toISOString();
const renamedFilename = date + '_' + safeTags.join('_') + '_' + meta.originalFilename;
const summaryFilePath = meta.summaryDir + '\\' + meta.baseName + '.md';
const renamedPath = meta.inboxDir + '\\' + renamedFilename;

const summaryMarkdown = [
  '# ' + meta.baseName,
  '',
  '## Summary',
  ...points.map((point) => '- ' + point),
  '',
  '## Tags',
  ...tags.map((tag) => '- ' + tag),
  '',
  '_Processed: ' + timestamp + '_',
  ''
].join('\n');

const psLiteral = (value) => "'" + String(value).replace(/'/g, "''") + "'";
const renameScript = [
  "$ErrorActionPreference = 'Stop'",
  'Move-Item -LiteralPath ' + psLiteral(meta.sourcePath) + ' -Destination ' + psLiteral(renamedPath) + ' -Force'
].join("\r\n");

return [{
  json: {
    ...meta,
    summaryPoints: points,
    tags,
    safeTags,
    timestamp,
    summaryMarkdown,
    summaryFilePath,
    renamedFilename,
    renamedPath,
    renameCommand: 'powershell.exe -NoProfile -NonInteractive -ExecutionPolicy Bypass -EncodedCommand ' + Buffer.from(renameScript, 'utf16le').toString('base64')
  }
}];

const meta = $node['Prepare Input'].json;
const text = String($json.text ?? $json.stdout ?? '')
  .replace(/\u0000/g, '')
  .replace(/\r\n/g, '\n')
  .trim();

if (!text) throw new Error('No plain text could be extracted from the document.');

return [{
  json: {
    ...meta,
    text
  }
}];

const path = String($json.path || '').replace(/\//g, '\\');
if (!path) return [];

const originalFilename = path.split('\\').pop();
const extensionMatch = originalFilename.match(/(\.[^.]+)$/);
const extension = extensionMatch ? extensionMatch[1].toLowerCase() : '';

// Process only new PDF and DOCX files. Ignore the date-prefixed files created by this workflow.
if (!['.pdf', '.docx'].includes(extension)) return [];
if (/^\d{4}-\d{2}-\d{2}_[^_]+_[^_]+_[^_]+_/i.test(originalFilename)) return [];

const baseName = originalFilename.slice(0, -extension.length);
const inboxDir = 'C:\\Users\\YOUR_WINDOWS_USERNAME\\.n8n-files\\inbox';
const summaryDir = 'C:\\Users\\YOUR_WINDOWS_USERNAME\\.n8n-files\\summary';
const failedDir = 'C:\\Users\\YOUR_WINDOWS_USERNAME\\.n8n-files\\failed';
const psLiteral = (value) => "'" + String(value).replace(/'/g, "''") + "'";

const docxScript = [
  "$ErrorActionPreference = 'Stop'",
  '[Console]::OutputEncoding = [System.Text.Encoding]::UTF8',
  'Add-Type -AssemblyName System.IO.Compression.FileSystem',
  '$archive = [System.IO.Compression.ZipFile]::OpenRead(' + psLiteral(path) + ')',
  'try {',
  "  $entry = $archive.GetEntry('word/document.xml')",
  "  if ($null -eq $entry) { throw 'word/document.xml was not found in the DOCX file.' }",
  '  $stream = $entry.Open()',
  '  try {',
  '    $reader = New-Object System.IO.StreamReader($stream, [System.Text.Encoding]::UTF8)',
  '    try { $xmlText = $reader.ReadToEnd() } finally { $reader.Dispose() }',
  '  } finally { $stream.Dispose() }',
  '  $doc = New-Object System.Xml.XmlDocument',
  '  $doc.LoadXml($xmlText)',
  '  $ns = New-Object System.Xml.XmlNamespaceManager($doc.NameTable)',
  "  $ns.AddNamespace('w', 'http://schemas.openxmlformats.org/wordprocessingml/2006/main')",
  "  $paragraphs = foreach ($paragraph in $doc.SelectNodes('//w:body/w:p', $ns)) {",
  "    $parts = foreach ($textNode in $paragraph.SelectNodes('.//w:t', $ns)) { $textNode.InnerText }",
  "    $line = ($parts -join '').Trim()",
  '    if ($line) { $line }',
  '  }',
  '  [Console]::Write(($paragraphs -join [Environment]::NewLine))',
  '} finally { $archive.Dispose() }'
].join("\r\n");

return [{
  json: {
    sourcePath: path,
    originalFilename,
    baseName,
    extension,
    inboxDir,
    summaryDir,
    failedDir,
    docxExtractCommand: 'powershell.exe -NoProfile -NonInteractive -ExecutionPolicy Bypass -EncodedCommand ' + Buffer.from(docxScript, 'utf16le').toString('base64')
  }
}];
